<x-app-layout>
    <x-slot name="header"><h2 class="font-semibold text-xl text-gray-800 leading-tight">Beneficiary GIS Map</h2></x-slot>

    <div class="py-6"><div class="max-w-7xl mx-auto sm:px-6 lg:px-8">
        <section class="map-shell">
            <div class="map-toolbar">
                <div class="map-title-block"><span class="map-title-icon" aria-hidden="true">&#9678;</span><div><p class="map-eyebrow">AICS geographic distribution</p><h3>Tagudin beneficiary map</h3><p id="map-status">Loading GIS layers&hellip;</p></div></div>
                <div class="map-toolbar-actions"><span class="map-live-indicator"><i></i> Live view</span><button id="filter-toggle" class="map-control-button" type="button">Filters <span>&darr;</span></button></div>
            </div>
            <form id="filter-form" class="map-filters" hidden>
                <label>Search<input name="search" placeholder="Name or case ID"></label>
                <label>Barangay<select name="barangay_id"><option value="">All barangays</option>@foreach($barangays as $barangay)<option value="{{ $barangay->id }}">{{ $barangay->name }}</option>@endforeach</select></label>
                <label>Status<select name="status"><option value="">All statuses</option><option>Pending</option><option>Approved</option><option>Released</option><option>Completed</option></select></label>
                <label>From<input type="date" name="from"></label><label>To<input type="date" name="to"></label>
                <button class="map-apply" type="submit">Apply filters</button>
            </form>
            <div class="map-stage"><div class="map-corner-label"><span>TAGUDIN, ILOCOS SUR</span><b>Beneficiary distribution</b></div><div id="map" aria-label="Interactive map of Tagudin beneficiaries"></div>
                <aside class="map-legend" id="map-legend"><div class="legend-heading"><strong>Assistance type</strong><button id="legend-toggle" type="button" aria-expanded="true">−</button></div><div id="legend-items"></div><button id="boundary-toggle" class="boundary-toggle" type="button">Hide barangay borders</button></aside>
            </div>
        </section>
    </div></div>

    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
    <link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.4.1/dist/MarkerCluster.css">
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <script src="https://unpkg.com/leaflet.markercluster@1.4.1/dist/leaflet.markercluster.js"></script>
    <script>
    (() => {
        const map = L.map('map', { zoomControl: false }).setView([16.9301, 120.3604], 12);
        L.control.zoom({ position: 'bottomright' }).addTo(map);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '&copy; OpenStreetMap contributors', maxZoom: 19 }).addTo(map);
        const endpoint = @json(route('map.data')), boundaryEndpoint = @json(route('map.boundaries'));
        const form = document.getElementById('filter-form'), statusLine = document.getElementById('map-status');
        const categoryTypes = @json($assistanceTypes); let activeCategories = new Set(categoryTypes.map(type => String(type.id)));
        let allRecords = [], boundaryLayer, boundariesShown = true, tagudinBounds;
        const clusters = L.markerClusterGroup({ chunkedLoading: true, showCoverageOnHover: false, maxClusterRadius: 48, disableClusteringAtZoom: 15, spiderfyOnMaxZoom: true, iconCreateFunction: clusterIcon });
        map.addLayer(clusters);

        function escapeHtml(value) { const div = document.createElement('div'); div.textContent = value ?? ''; return div.innerHTML; }
        function isPending(status) { return String(status).toLowerCase() === 'pending'; }
        function markerSize() { return map.getZoom() >= 16 ? 17 : map.getZoom() >= 14 ? 14 : 11; }
        function markerIcon(record) { const size = markerSize(), pending = isPending(record.status); return L.divIcon({ className: 'beneficiary-marker-wrap', iconSize: [size + 8, size + 8], iconAnchor: [(size + 8) / 2, (size + 8) / 2], html: `<span class="beneficiary-marker ${pending ? 'is-pending' : ''}" style="--marker-color:${record.category.color};--marker-size:${size}px" aria-label="${escapeHtml(record.category.name)}"><b>${escapeHtml(record.category.icon)}</b></span>` }); }
        function statusClass(status) { return String(status).toLowerCase().replace(/\s+/g, '-'); }
        function popup(record) { const d = record.details, canViewCase = d.case_record_id && d.case_number; const amount = d.amount ? `₱${Number(d.amount).toLocaleString('en-PH', { minimumFractionDigits: 2 })}` : 'Not recorded'; return `<article class="beneficiary-popup" style="--category-color:${record.category.color}"><header><span class="category-icon">${escapeHtml(record.category.icon)}</span><div><b>${escapeHtml(record.category.name)}</b><small>Assistance category</small></div></header><dl><div><dt>Barangay</dt><dd>${escapeHtml(record.barangay || 'Unassigned')}</dd></div><div><dt>Date availed</dt><dd>${record.date_availed ? new Date(record.date_availed + 'T00:00:00').toLocaleDateString('en-PH', { month:'short', day:'numeric', year:'numeric' }) : 'Not recorded'}</dd></div><div><dt>Status</dt><dd><span class="status-badge ${statusClass(record.status)}">${escapeHtml(record.status)}</span></dd></div><div><dt>Beneficiary</dt><dd>${escapeHtml(d.name)}</dd></div><div><dt>Case reference</dt><dd>${escapeHtml(d.case_number || d.reference_code || 'Not assigned')}</dd></div><div><dt>Amount granted</dt><dd>${amount}</dd></div><div><dt>Social Officer</dt><dd>${escapeHtml(d.social_officer || 'Not assigned')}</dd></div></dl>${canViewCase ? `<a class="case-link" href="/case-records/${d.case_record_id}">View full case record <span>→</span></a>` : ''}</article>`; }
        function clusterIcon(cluster) { const markers = cluster.getAllChildMarkers(), counts = {}; markers.forEach(marker => { const r = marker.options.record; counts[r.category.color] = (counts[r.category.color] || 0) + 1; }); const total = markers.length; let position = 0; const slices = Object.entries(counts).map(([color,count]) => { const end = position + count / total * 360; const slice = `${color} ${position}deg ${end}deg`; position = end; return slice; }).join(', '); return L.divIcon({ className:'category-cluster-wrap', iconSize:[44,44], iconAnchor:[22,22], html:`<span class="category-cluster" style="background:conic-gradient(${slices})"><b>${total}</b></span>` }); }
        function drawRecords() { clusters.clearLayers(); allRecords.filter(r => activeCategories.has(String(r.category.id))).forEach((record, index) => { const marker = L.marker([record.latitude, record.longitude], { icon: markerIcon(record), record, riseOnHover:true, keyboard:true }); marker.bindPopup(popup(record), { maxWidth: 280, className:'beneficiary-popup-wrap', closeButton:true, autoPanPadding:[24,24] }); marker.on('click', () => marker.getElement()?.classList.add('marker-pulse')); marker.on('popupclose', () => marker.getElement()?.classList.remove('marker-pulse')); marker.on('add', () => { const e = marker.getElement(); if (e && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) e.style.animationDelay = `${Math.random() * 300}ms`; }); clusters.addLayer(marker); }); statusLine.textContent = `${allRecords.filter(r => activeCategories.has(String(r.category.id))).length} geotagged record(s) shown.`; }
        function renderLegend() { document.getElementById('legend-items').innerHTML = categoryTypes.map(type => `<button class="legend-item ${activeCategories.has(String(type.id)) ? 'is-active' : 'is-hidden'}" data-category="${type.id}" type="button"><span class="legend-symbol" style="--marker-color:${type.color}">${escapeHtml(type.icon)}</span><span>${escapeHtml(type.name)}</span><i>✓</i></button>`).join(''); document.querySelectorAll('.legend-item').forEach(button => button.addEventListener('click', () => { const id = button.dataset.category; activeCategories.has(id) ? activeCategories.delete(id) : activeCategories.add(id); renderLegend(); drawRecords(); })); }
        async function loadBoundaries() { const response = await fetch(boundaryEndpoint), geojson = await response.json(); if (!geojson.features?.length) return; boundaryLayer = L.geoJSON(geojson, { style:{ color:'#1565c0', weight:1.25, fillColor:'#e8f1fb', fillOpacity:.16 }, onEachFeature:(feature, layer) => { const name = feature.properties?.adm4_en || feature.properties?.name || 'Barangay'; layer.bindTooltip(name, { className:'barangay-label', sticky:true }); layer.on('click', () => { const option = [...form.elements.barangay_id.options].find(item => item.text === name); if (option) form.elements.barangay_id.value = option.value; form.dispatchEvent(new Event('submit')); }); }}).addTo(map); tagudinBounds = boundaryLayer.getBounds(); map.fitBounds(tagudinBounds.pad(.04)); }
        async function loadData() { statusLine.textContent = 'Updating map records…'; const response = await fetch(`${endpoint}?${new URLSearchParams(new FormData(form))}`); const payload = await response.json(); allRecords = payload.beneficiaries; drawRecords(); }
        document.getElementById('filter-toggle').onclick = () => { form.hidden = !form.hidden; };
        document.getElementById('legend-toggle').onclick = event => { const legend = document.getElementById('map-legend'); legend.classList.toggle('is-collapsed'); event.currentTarget.textContent = legend.classList.contains('is-collapsed') ? '+' : '−'; event.currentTarget.setAttribute('aria-expanded', String(!legend.classList.contains('is-collapsed'))); };
        document.getElementById('boundary-toggle').onclick = event => { boundariesShown = !boundariesShown; if (boundaryLayer) boundariesShown ? boundaryLayer.addTo(map) : boundaryLayer.remove(); event.currentTarget.textContent = boundariesShown ? 'Hide barangay borders' : 'Show barangay borders'; };
        form.addEventListener('submit', event => { event.preventDefault(); loadData(); }); map.on('zoomend', drawRecords);
        renderLegend(); loadBoundaries().then(loadData).catch(() => statusLine.textContent = 'Unable to load map records. Please try again.');
    })();
    </script>
    <style>
    .map-shell{overflow:hidden;border:1px solid #dce8f7;border-radius:16px;background:#fff;box-shadow:0 12px 30px #073d8214}.map-toolbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.3rem 1.4rem;border-bottom:1px solid #e7eff8}.map-toolbar h3{margin:.12rem 0;color:#073d82;font-size:1.22rem}.map-eyebrow{margin:0;color:#1565c0;font-size:.67rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.map-toolbar p:last-child{margin:.25rem 0 0;color:#718198;font-size:.78rem}.map-control-button,.map-apply{border:0;border-radius:8px;padding:.65rem .9rem;color:#fff;background:#1565c0;font-size:.8rem;font-weight:800;cursor:pointer;box-shadow:0 4px 10px #1565c025}.map-filters{display:grid;grid-template-columns:1.5fr repeat(4,1fr) auto;gap:.75rem;align-items:end;padding:1rem 1.4rem;border-bottom:1px solid #e7eff8;background:#f7faff}.map-filters label{display:grid;gap:.3rem;color:#52627a;font-size:.72rem;font-weight:700}.map-filters input,.map-filters select{min-width:0;border:1px solid #cddcec;border-radius:7px;padding:.56rem .62rem;color:#274667;background:#fff;font-size:.8rem}.map-stage{position:relative}.map-stage #map{height:650px}.map-legend{position:absolute;z-index:500;bottom:18px;left:18px;width:210px;border:1px solid #d8e5f2;border-radius:11px;padding:.75rem;background:#fffffff2;box-shadow:0 10px 25px #073d8226;backdrop-filter:blur(7px)}.legend-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:.45rem;color:#073d82;font-size:.8rem}.legend-heading button{border:0;color:#1565c0;background:transparent;font-size:1.25rem;cursor:pointer}.legend-item{display:flex;align-items:center;gap:.55rem;width:100%;border:0;border-radius:6px;padding:.35rem;background:transparent;color:#38536f;font-size:.75rem;text-align:left;cursor:pointer}.legend-item:hover{background:#edf5ff}.legend-item i{margin-left:auto;color:#2e7d32;font-style:normal}.legend-item.is-hidden{opacity:.46}.legend-item.is-hidden i{visibility:hidden}.legend-symbol{display:grid;place-items:center;width:17px;height:17px;border:1.5px solid #fff;border-radius:50%;color:#fff;background:var(--marker-color);font-size:10px;line-height:1;box-shadow:0 1px 3px #073d8250}.boundary-toggle{width:100%;margin-top:.55rem;border:1px solid #bdd2e8;border-radius:6px;padding:.4rem;color:#1565c0;background:#fff;font-size:.7rem;font-weight:700;cursor:pointer}.map-legend.is-collapsed #legend-items,.map-legend.is-collapsed .boundary-toggle{display:none}.beneficiary-marker-wrap{background:transparent!important;border:0!important}.beneficiary-marker{display:grid;place-items:center;width:var(--marker-size);height:var(--marker-size);border:2px solid #fff;border-radius:50%;color:#fff;background:var(--marker-color);box-shadow:0 2px 6px #052b5b75;transition:transform .18s ease-out,box-shadow .18s ease-out;animation:marker-in .28s ease-out both}.beneficiary-marker b{font-size:calc(var(--marker-size) * .58);line-height:1}.beneficiary-marker.is-pending{opacity:.54;background:#fff;color:var(--marker-color);border-color:var(--marker-color);box-shadow:0 0 0 2px #fff,0 2px 6px #052b5b50}.leaflet-marker-icon:hover .beneficiary-marker{transform:scale(1.2);box-shadow:0 4px 10px #052b5b8c}.marker-pulse .beneficiary-marker:after{position:absolute;inset:-6px;border:2px solid var(--marker-color);border-radius:50%;content:"";animation:marker-ring .45s ease-out}.category-cluster-wrap{background:transparent!important;border:0!important}.category-cluster{display:grid;place-items:center;width:40px;height:40px;border:2px solid #fff;border-radius:50%;box-shadow:0 3px 8px #052b5b70}.category-cluster b{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;color:#073d82;background:#fff;font-size:.72rem}.beneficiary-popup-wrap .leaflet-popup-content-wrapper{border-radius:10px;padding:0;box-shadow:0 12px 30px #052b5b38}.beneficiary-popup-wrap .leaflet-popup-content{width:260px!important;margin:0}.beneficiary-popup{overflow:hidden;border-top:4px solid var(--category-color);color:#314c68}.beneficiary-popup header{display:flex;gap:.6rem;align-items:center;padding:.85rem .9rem .65rem;color:#073d82}.beneficiary-popup header small{display:block;margin-top:.1rem;color:#718198;font-size:.66rem}.category-icon{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;color:#fff;background:var(--category-color);font-weight:800}.beneficiary-popup dl{display:grid;grid-template-columns:1fr 1fr;gap:.55rem;margin:0;padding:.15rem .9rem .85rem}.beneficiary-popup dl div{min-width:0}.beneficiary-popup dt{margin-bottom:.1rem;color:#7b8ca1;font-size:.62rem;font-weight:800;text-transform:uppercase}.beneficiary-popup dd{overflow:hidden;margin:0;color:#284561;font-size:.73rem;font-weight:700;text-overflow:ellipsis;white-space:nowrap}.status-badge{display:inline-block;border-radius:99px;padding:.17rem .42rem;font-size:.64rem}.status-badge.pending{color:#8a5b00;background:#fff3cd}.status-badge.approved,.status-badge.released,.status-badge.completed{color:#1d6b39;background:#e4f5e9}.case-link{display:flex;justify-content:space-between;padding:.65rem .9rem;color:#fff;background:#1565c0;font-size:.73rem;font-weight:800;text-decoration:none}.case-link:hover{background:#0d4f9b}.barangay-label{border:0!important;border-radius:4px!important;padding:2px 4px!important;color:#073d82!important;background:#ffffffe0!important;font-size:10px!important;font-weight:700!important;box-shadow:0 1px 3px #052b5b20}@keyframes marker-in{from{opacity:0;transform:scale(.35)}to{opacity:1;transform:scale(1)}}@keyframes marker-ring{to{opacity:0;transform:scale(1.65)}}@media(max-width:700px){.map-toolbar{align-items:flex-start}.map-filters{grid-template-columns:1fr 1fr}.map-filters label:first-child{grid-column:1/-1}.map-apply{grid-column:1/-1}.map-stage #map{height:580px}.map-legend{bottom:14px;left:12px;width:190px}}@media(prefers-reduced-motion:reduce){.beneficiary-marker,.beneficiary-marker:after{animation:none!important;transition:none!important}}
    </style>
    <style>
    /* Operations-map redesign: the controls read as one calm workspace, while the map stays central. */
    .map-shell{border:0;border-radius:22px;background:#073d82;box-shadow:0 20px 48px rgba(7,61,130,.18)}
    .map-toolbar{min-height:110px;padding:1.5rem 1.65rem;border:0;color:#fff;background:linear-gradient(120deg,#06366f 0%,#1565c0 68%,#1b78cc 100%)}
